import { $authHost } from "./index";

export const sendClicksToServer = async (userId, clicks) => {
    try {
        const response = await $authHost.post(`/api/add-coins/${userId}`, { 
            clicks 
        });
        
        if (response.data?.success) {
            return {
                success: true,
                user: response.data.user || null,
                energy: response.data.user?.energy,
                coins: response.data.user?.money
            };
        }
        
        throw new Error(response.data?.message || 'Failed to send clicks');
    } catch (error) {
        console.error('Error sending clicks:', error);
        throw error;
    }
};

export const getPlayerData = async () => {
    try {
        const response = await $authHost.get('/api/player');
        
        if (response.data?.success) {
            return {
                success: true,
                player: response.data.player
            };
        }
        
        throw new Error(response.data?.message || 'Failed to get player data');
    } catch (error) {
        console.error('Error getting player data:', error);
        throw error;
    }
};

export const updateEnergyOnServer = async (userId, energy) => {
    try {
        const response = await $authHost.put(`/api/update-energy/${userId}`, { 
            energy 
        });
        
        return response.data?.success || false;
    } catch (error) {
        console.error('Error updating energy:', error);
        return false;
    }
};

export const checkConnection = async () => {
    try {
        const response = await $authHost.get('/api/health');
        return response.data?.success || false;
    } catch (error) {
        console.error('Connection check failed:', error);
        return false;
    }
};