import React, { useEffect, useState, useCallback, useMemo } from 'react';
import Clicker from "../Clicker/Clicker";
import cl from "./ClickerAndBuff.module.css";
import { usePlayerStore } from '../../../store/playerStore.mjs';
import { useTranslation } from "../../../hooks/useTranslation";

const EnergyText = React.memo(({ energy, maxEnergy }) => (
    <div className={cl.text}>
        {energy}/{maxEnergy}
    </div>
));

EnergyText.displayName = 'EnergyText';

const BoostText = React.memo(({ text }) => (
    <div className={cl.text}>
        {text}
    </div>
));

BoostText.displayName = 'BoostText';

const ClickerAndBuff = ({ setBoost, url }) => {
    const player = usePlayerStore((state) => state.player);
    const [energy, setEnergy] = useState(0);
    const language = localStorage.getItem('language') || 'en';
    const { t } = useTranslation(language);

    const maxEnergy = useMemo(() => {
        const limitEnergy = player?.boost?.energiLimit?.level === 1 ? 0 : (player?.boost?.energiLimit?.level || 0) * 100;
        return 500 + (limitEnergy || 0);
    }, [player?.boost?.energiLimit?.level]);

    useEffect(() => {
        if (player?.energy !== undefined) {
            setEnergy(player.energy);
        }
    }, [player?.energy]);

    const handleEnergyClick = useCallback(() => {
        setBoost(true);
    }, [setBoost]);

    const handleBoostClick = useCallback(() => {
        setBoost(true);
    }, [setBoost]);

    const boostText = useMemo(() => t('ClickerAndBuff.boost'), [t]);

    return (
        <div className={cl.clickerAndBuff__container}>
            <Clicker url={url} />
            <div className={cl.wallet__container}>
            </div>
            <div className={`${cl.energyAndBoost__container} ${cl.mt_1}`}>
                <div onClick={handleEnergyClick} className={cl.energy__item}>
                    <div className={cl.icon}>
                        <img 
                            src={require("../../images/lightning.webp")} 
                            alt="energy" 
                            loading="lazy"
                        />
                    </div>
                    <EnergyText energy={energy} maxEnergy={maxEnergy} />
                </div>
                <button onClick={handleBoostClick} className={cl.boost__item}>
                    <div className={cl.icon}>
                        <img 
                            src={require("../../images/rocket.webp")} 
                            alt="boost" 
                            loading="lazy"
                        />
                    </div>
                    <BoostText text={boostText} />
                </button>
            </div>
        </div>
    );
};

export default React.memo(ClickerAndBuff);