import React, { useState, useEffect, useRef, useCallback } from 'react';
import cl from './Clicker.module.css';
import { usePlayerStore } from '../../../store/playerStore.mjs';
import { useTelegram } from "../../../components/hooks/useTelegram";
import { sendClicksToServer } from '../../../http/cliker';

const ENERGY_REGEN_RATE = 1;
const CLICK_SEND_DELAY = 1500;
const MAX_CLICKS_PER_SECOND = 14;
const AUTO_CLICKS_PER_INTERVAL = 7;
const CLICK_INTERVAL = 1000 / MAX_CLICKS_PER_SECOND;
const HOLD_DELAY = 300;

const Clicker = () => {
    const { player, updatePlayer, updateEnergy } = usePlayerStore();
    const [isShaking, setIsShaking] = useState(false);
    const [isPressed, setIsPressed] = useState(false);
    const clickCountRef = useRef(0);
    const autoClickIntervalRef = useRef(null);
    const holdTimeoutRef = useRef(null);
    const lastClickTimeRef = useRef(0);
    const { tg } = useTelegram();

    const limitEnergy = player?.boost?.energiLimit?.level === 1 ? 0 : (player?.boost?.energiLimit?.level || 0) * 100;
    const MAX_ENERGY = 500 + limitEnergy;

    const performClick = useCallback(() => {
        if (!player || player.energy <= 0) return;

        const now = Date.now();
        const timeSinceLastClick = now - lastClickTimeRef.current;
        
        if (timeSinceLastClick < CLICK_INTERVAL) {
            return;
        }
        
        lastClickTimeRef.current = now;

        if (tg?.HapticFeedback?.impactOccurred) {
            tg.HapticFeedback.impactOccurred('light');
        }

        setIsShaking(true);
        const clickMultiplier = player?.boost?.multiplier?.level > 0 ? player?.boost?.multiplier?.level : 1;
        
        clickCountRef.current += clickMultiplier;

        updatePlayer({
            energy: Math.max(0, player.energy - 1),
            money: player.money + clickMultiplier,
        });

        setTimeout(() => setIsShaking(false), 200);
    }, [player, tg, updatePlayer]);

    const handleClick = useCallback(() => {
        performClick();
    }, [performClick]);

    const handleKeyDown = useCallback((e) => {
        if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
            e.preventDefault();
            performClick();
        }
    }, [performClick]);

    const handleMouseDown = useCallback(() => {
        console.log('Mouse DOWN');
        setIsPressed(true);
        performClick();
        
        holdTimeoutRef.current = setTimeout(() => {
            console.log('Starting auto-clicks');
            startAutoClicks();
        }, HOLD_DELAY);
    }, [performClick]);

    const handleMouseUp = useCallback(() => {
        console.log('Mouse UP');
        setIsPressed(false);
        
        if (holdTimeoutRef.current) {
            clearTimeout(holdTimeoutRef.current);
            holdTimeoutRef.current = null;
        }
        
        if (autoClickIntervalRef.current) {
            clearInterval(autoClickIntervalRef.current);
            autoClickIntervalRef.current = null;
        }
    }, []);

    const startAutoClicks = useCallback(() => {
        if (autoClickIntervalRef.current) {
            return;
        }
        
        console.log('Auto-clicks started');
        let autoClickCount = 0;
        
        autoClickIntervalRef.current = setInterval(() => {
            if (autoClickCount >= AUTO_CLICKS_PER_INTERVAL) {
                console.log('Auto-clicks finished');
                clearInterval(autoClickIntervalRef.current);
                autoClickIntervalRef.current = null;
                return;
            }
            
            performClick();
            autoClickCount++;
        }, CLICK_INTERVAL);
    }, [performClick]);

    const sendClickData = useCallback(async () => {
        if (clickCountRef.current > 0 && player?.id) {
            const currentClickCount = clickCountRef.current;
            clickCountRef.current = 0; 
            
            try {
                const result = await sendClicksToServer(player.id, currentClickCount);
                
                if (result.success && result.energy !== undefined) {
                    updateEnergy(result.energy);
                }
            } catch (error) {
                console.error('Error sending click data:', error);
                clickCountRef.current += currentClickCount;
            }
        }
    }, [player?.id, updateEnergy]);

    useEffect(() => {
        const clickInterval = setInterval(() => {
            if (clickCountRef.current > 0) {
                sendClickData();
            }
        }, CLICK_SEND_DELAY);

        return () => clearInterval(clickInterval);
    }, [sendClickData]);

    const regenerateEnergy = useCallback(() => {
        if (player && player.energy < MAX_ENERGY) {
            updateEnergy(Math.min(MAX_ENERGY, player.energy + ENERGY_REGEN_RATE));
        }
    }, [player, MAX_ENERGY, updateEnergy]);

    useEffect(() => {
        const regenInterval = setInterval(() => {
            regenerateEnergy();
        }, 1000);

        return () => clearInterval(regenInterval);
    }, [regenerateEnergy]);

    useEffect(() => {
        const handleGlobalKeyDown = (e) => {
            if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
                e.preventDefault();
                console.log('Key DOWN:', e.key);
                if (!isPressed) {
                    handleMouseDown();
                }
            }
        };

        const handleGlobalKeyUp = (e) => {
            if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
                e.preventDefault();
                console.log('Key UP:', e.key);
                if (isPressed) {
                    handleMouseUp();
                }
            }
        };

        window.addEventListener('keydown', handleGlobalKeyDown);
        window.addEventListener('keyup', handleGlobalKeyUp);

        return () => {
            window.removeEventListener('keydown', handleGlobalKeyDown);
            window.removeEventListener('keyup', handleGlobalKeyUp);
            
            if (holdTimeoutRef.current) {
                clearTimeout(holdTimeoutRef.current);
            }
            if (autoClickIntervalRef.current) {
                clearInterval(autoClickIntervalRef.current);
            }
        };
    }, [isPressed, handleMouseDown, handleMouseUp]);

    useEffect(() => {
        const handleBlur = () => {
            console.log('Window blur');
            if (isPressed) {
                handleMouseUp();
            }
        };

        window.addEventListener('blur', handleBlur);
        return () => window.removeEventListener('blur', handleBlur);
    }, [isPressed, handleMouseUp]);

    const buttonClasses = [
        cl.clicker__btn,
        isShaking ? cl.scaleDo : '',
        isPressed ? cl.pressed : '',
        autoClickIntervalRef.current ? cl.autoClicking : ''
    ].filter(Boolean).join(' ');

    return (
        <div className={cl.container__clicker}>
            <div
                className={buttonClasses}
                onClick={handleClick}
                onMouseDown={handleMouseDown}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
                onTouchStart={handleMouseDown}
                onTouchEnd={handleMouseUp}
                onTouchCancel={handleMouseUp}
                role="button"
                tabIndex={0}
                aria-label="Click to earn coins"
                aria-pressed={isPressed}
                onKeyDown={handleKeyDown}
                style={{
                    cursor: 'pointer',
                    userSelect: 'none',
                    outline: 'none',
                }}
            />
        </div>
    );
};

export default React.memo(Clicker);